<script setup>
import { computed, onMounted, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { adminBlindboxes, createBlindbox, changeBlindboxStatus, adminPrizes } from '../../api/blindbox'
import { adminAlbums } from '../../api/admin'
import PageTitle from '../../components/PageTitle.vue'
import MediaUploader from '../../components/MediaUploader.vue'
const rows=ref([]),loading=ref(false),saving=ref(false),prizeSaving=ref(false),dialog=ref(false),prizeDialog=ref(false),target=ref(null),form=ref({name:'',albumId:'',price:'',totalCount:1,description:'',coverUrl:'',prizes:[]}),prize=ref({prizeName:'',prizeLevel:1,probability:1,imageUrl:'',description:''})
const prizeOptions=[{value:1,label:'SSR'},{value:2,label:'SR'},{value:3,label:'R'},{value:4,label:'N'}]
const albums=ref([]),albumLoading=ref(false)
const albumOptions=computed(()=>albums.value.map(a=>({value:a.id,label:`#${a.id} ${a.title} · ${a.artist}`})))
function albumTitle(id){const a=albums.value.find(x=>x.id===id);return a?`${a.title} · ${a.artist}`:`#${id}`}
async function loadAlbumOptions(){albumLoading.value=true;try{const p=await adminAlbums({current:1,size:100});albums.value=p?.records||[]}finally{albumLoading.value=false}}
function addPrizeRow(){form.value.prizes.push({prizeName:'',prizeLevel:4,probability:1,imageUrl:'',description:''})}
function validatePrizes(list){if(!list.length)return '请至少配置一个奖品';if(list.some(p=>!p.prizeName||!p.prizeName.trim()))return '奖品名称不能为空';if(list.some(p=>!(Number(p.probability)>0)))return '奖品概率必须大于 0';if(!list.some(p=>Number(p.prizeLevel)===1)||!list.some(p=>Number(p.prizeLevel)===2))return '奖池必须同时包含 SSR 和 SR 奖品（保底机制要求）';return ''}
async function load(){loading.value=true;try{const p=await adminBlindboxes({current:1,size:50});rows.value=p?.records||[]}finally{loading.value=false}}
async function save(){if(saving.value)return;const f=form.value,error=validatePrizes(f.prizes);if(error)return ElMessage.error(error);if(!f.albumId)return ElMessage.error('请选择关联专辑');saving.value=true;try{await createBlindbox({name:f.name,albumId:Number(f.albumId),price:Number(f.price),totalCount:Number(f.totalCount),description:f.description||null,coverUrl:f.coverUrl||null,prizes:f.prizes.map(p=>({prizeName:p.prizeName.trim(),prizeLevel:Number(p.prizeLevel),probability:Number(p.probability),imageUrl:p.imageUrl||null,description:p.description||null}))});ElMessage.success('盲盒已创建');dialog.value=false;await load()}finally{saving.value=false}}
async function toggle(row){await changeBlindboxStatus(row.id,Number(row.status)===1?0:1);ElMessage.success('状态已更新');load()}
async function addPrize(){if(prizeSaving.value||!target.value)return;prizeSaving.value=true;try{await adminPrizes(target.value.id,{...prize.value,probability:Number(prize.value.probability),prizeLevel:Number(prize.value.prizeLevel),imageUrl:prize.value.imageUrl||null,description:prize.value.description||null});prizeDialog.value=false;ElMessage.success('奖品已添加');await load()}finally{prizeSaving.value=false}}
onMounted(()=>{load();loadAlbumOptions()})
</script>
<template><div class="admin-page"><PageTitle eyebrow="MYSTERY EDITION" title="盲盒管理"/><div class="toolbar"><el-button type="primary" @click="dialog=true">新建盲盒</el-button><el-button @click="load">刷新</el-button></div><el-table v-loading="loading" :data="rows"><el-table-column label="封面" width="90"><template #default="{row}"><img v-if="row.coverUrl" :src="row.coverUrl" :alt="row.name" width="64" height="64" style="object-fit:cover;border-radius:8px"/><span v-else>—</span></template></el-table-column><el-table-column prop="id" label="ID" width="80"/><el-table-column prop="name" label="名称"/><el-table-column label="关联专辑" min-width="140"><template #default="{row}">{{ albumTitle(row.albumId) }}</template></el-table-column><el-table-column prop="price" label="价格"/><el-table-column prop="remainCount" label="剩余库存"/><el-table-column prop="status" label="状态"><template #default="{row}">{{Number(row.status)===1?'上架':'下架'}}</template></el-table-column><el-table-column label="操作" width="220"><template #default="{row}"><el-button text @click="toggle(row)">{{Number(row.status)===1?'下架':'上架'}}</el-button><el-button text @click="target=row;prizeDialog=true">添加奖品</el-button></template></el-table-column></el-table><el-dialog v-model="dialog" title="创建盲盒" width="min(700px,94vw)"><el-form label-position="top"><div class="form-grid"><el-form-item label="盲盒名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="关联专辑"><el-select v-model="form.albumId" filterable :loading="albumLoading" placeholder="输入专辑名或艺人搜索并选择" style="width:100%"><el-option v-for="opt in albumOptions" :key="opt.value" :label="opt.label" :value="opt.value"/></el-select></el-form-item><el-form-item label="价格"><el-input v-model="form.price" type="number"/></el-form-item><el-form-item label="总库存"><el-input v-model="form.totalCount" type="number"/></el-form-item><el-form-item label="封面图片 URL" class="span-2"><el-input v-model="form.coverUrl" placeholder="/media/image/盲盒封面文件名.jpg 或上传后自动填入"/><MediaUploader kind="image" @uploaded="form.coverUrl = $event"/></el-form-item><el-form-item label="描述" class="span-2"><el-input v-model="form.description"/></el-form-item><el-form-item class="span-2"><template #label><span>奖品配置（奖池）　<span class="muted">至少含 SSR 与 SR 各一个；概率为相对权重，无需合计 100</span></span></template><div v-for="(p,i) in form.prizes" :key="i" style="border:1px solid var(--el-border-color);border-radius:8px;padding:10px 12px;margin-bottom:8px"><div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center"><el-input v-model="p.prizeName" placeholder="奖品名称" style="flex:2;min-width:150px"/><el-select v-model="p.prizeLevel" style="width:96px"><el-option v-for="opt in prizeOptions" :key="opt.value" :label="opt.label" :value="opt.value"/></el-select><el-input v-model="p.probability" type="number" placeholder="概率权重" style="width:110px"/><el-button text type="danger" @click="form.prizes.splice(i,1)">删除</el-button></div><div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin-top:8px"><el-input v-model="p.imageUrl" placeholder="奖品图片 URL（可留空）" style="flex:2;min-width:150px"/><MediaUploader kind="image" compact @uploaded="p.imageUrl = $event"/><el-input v-model="p.description" placeholder="说明（选填）" style="flex:1;min-width:130px"/></div></div><el-button @click="addPrizeRow">+ 添加奖品</el-button></el-form-item></div></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" :disabled="saving" @click="save">创建</el-button></template></el-dialog><el-dialog v-model="prizeDialog" title="添加奖品"><el-form label-position="top"><el-form-item label="奖品名称"><el-input v-model="prize.prizeName"/></el-form-item><el-form-item label="稀有度"><el-select v-model="prize.prizeLevel" style="width:100%"><el-option v-for="opt in prizeOptions" :key="opt.value" :label="opt.label" :value="opt.value"/></el-select></el-form-item><el-form-item label="概率权重"><el-input v-model="prize.probability" type="number"/></el-form-item><el-form-item label="图片 URL"><el-input v-model="prize.imageUrl"/><MediaUploader kind="image" @uploaded="prize.imageUrl = $event"/></el-form-item><el-form-item label="说明"><el-input v-model="prize.description"/></el-form-item></el-form><template #footer><el-button @click="prizeDialog=false">取消</el-button><el-button type="primary" :loading="prizeSaving" :disabled="prizeSaving" @click="addPrize">添加</el-button></template></el-dialog></div></template>
